from langflow.custom import Component
from langflow.inputs import MessageInput
from langflow.template import Output
from langflow.schema import Data, Message

class SelectInputComponent(Component):
    display_name = "Select First Non-Empty"
    description = "Returns Input 1 if present, otherwise Input 2."
    
    inputs = [
        MessageInput(name="input_1", display_name="Input 1"),
    ]
    
    outputs = [
        Output(display_name="Output Message", name="output_message", method="select_message"),
    ]

    def select_message(self) -> Message:
        txt1 = self.input_1.text if self.input_1 and hasattr(self.input_1, "text") else ""
        return Message(text=txt1)

